Create Table Fre_Quotation_DBCR                     -- خدمات عرض
( Id          BIGINT NOT NULL AUTO_INCREMENT,                         -- مفتاح رئيسي
  Quot_Id     BIGINT NOT NULL,                          -- مفتاح العرض
  nOrd        SMALLINT Default 0,                         -- مسلسل الإظهار
  Loc_Id      BIGINT Default 0,                         -- Location / 1 Origin / 2 Shipping / 3 Destination
  Cont_Id     BIGINT Default 0,                         -- المتعامل
  Serv_Id     BIGINT Default 0,                         -- الخدمة
  Item_Id     BIGINT Default 0,                         -- المادة
  Unit_Id     BIGINT Default 1,                         -- الوحدة
  Curn_Id     BIGINT Default 1,                         -- العملة
  Curn_Rate   DECIMAL(25,9) Default 1,                      -- سعر الصرف
  Qnt         DECIMAL(25,3) Default 0,                      -- الكمية
  Price       DECIMAL(25,3) Default 0,                      -- إفرادي
  CAmt        DECIMAL(25,3) Default 0,                      -- المبلغ عملة
  Amt         DECIMAL(25,2) Default 0,                      -- المبلغ محلي
  Rem         VARCHAR(250),                          -- البيان
  Ins_User    BIGINT,  Ins_Date  DATETIME,
  Upd_User    BIGINT,  Upd_Date  DATETIME,
