Create Table Fre_Job                     -- ملفات العمل الموحدة (محلي، دولي، تخليص جمركي)
( Id           BIGINT AUTO_INCREMENT,                       -- مفتاح رئيسي
  
  -- التنظيم والهيكلية
  Dept_Id      BIGINT Default 0,              -- النشاط
  Unit_Id      BIGINT Default 0,              -- القسم
  Oper_Id      BIGINT Default 0,              -- العملية
  Period_Id    BIGINT Default 0,              -- السنة
  Num          BIGINT Default 0,             -- رقم الملف
  dDate        DATETIME Default NOW(),             -- تاريخ الإنشاء
  Descr        VARCHAR(100),               -- وصف ملف العمل

  -- الأطراف والعقود
  Quot_Id      BIGINT Default 0,              -- مفتاح العرض
  Cont_Id      BIGINT Default 0,              -- المتعامل \ الزبون
  Cont_RId     INT Default 0,              -- المتعامل \ المورد
  Contr_Id     BIGINT Default 0,              -- عقد الزبون
  Contr_RId    MEDIUMINT Default 0,              -- عقد المورد
  Driv_Id      BIGINT Default 0,              -- السائق (مربوط بترميز)
  Truk_Id      BIGINT Default 0,              -- المركبة (مربوط بترميز)
  Emp_Id       BIGINT Default 0,              -- المشرف / المسؤول
  Owner_Id     BIGINT,                        -- منظم ملف العمل
  DCust        VARCHAR(100),               -- اسم الزبون الظاهر على الأوراق

  -- الشروط والموقع الجغرافي
  ITerm_Id     BIGINT Default 0,              -- Inco Term
  PTerm_Id     BIGINT Default 0,              -- Payment Term
  Mode_Id      BIGINT Default 2,              -- وضع التجميع: 0 عادي، 1 تجميع
  OCntry_Id    BIGINT Default 0,              -- بلد المصدر
  OCity_Id     BIGINT Default 0,              -- مدينة المصدر
  OPort_Id     BIGINT Default 0,              -- المعبر المصدر
  OSPort_Id    BIGINT Default 0,              -- الميناء المصدر
  OAPort_Id    BIGINT Default 0,              -- المطار المصدر
  OName        VARCHAR(100),               -- اسم المصدر (يدوي)
  OAddress     VARCHAR(250),               -- عنوان المصدر
  DCntry_Id    BIGINT Default 0,              -- بلد المقصد
  DCity_Id     BIGINT Default 0,              -- مدينة المقصد
  DPort_Id     BIGINT Default 0,              -- المعبر المقصد
  DSPort_Id    BIGINT Default 0,              -- الميناء المقصد
  DAPort_Id    BIGINT Default 0,              -- المطار المقصد
  DName        VARCHAR(100),               -- اسم المقصد (يدوي)
  DAddress     VARCHAR(250),               -- عنوان المقصد

  -- البضاعة والأبعاد
  Comod_Id     BIGINT Default 0,              -- البضاعة (ترميز)
  vComd        VARCHAR(250),               -- وصف البضاعة (يدوي)
  Ship         VARCHAR(250),               -- الشاحن
  Cons         VARCHAR(250),               -- المشحون إليه
  Qnt          DECIMAL(25,3) Default 0,           -- عدد الطرود
  Price        DECIMAL(25,3) Default 0,           -- السعر
  WNet         DECIMAL(25,3) Default 0,           -- الوزن الصافي
  WGros        DECIMAL(25,3) Default 0,           -- الوزن القائم
  WChrg        DECIMAL(25,3) Default 0,           -- الوزن المحاسب عليه
  Volume       DECIMAL(25,3) Default 0,           -- الحجم
  Dist         DECIMAL(25,3) Default 0,           -- المسافة
  ODist        DECIMAL(25,3) Default 0,           -- المسافة الزائدة
  SDM          DECIMAL(25,3) Default 0,           -- Supplier Loading Meter
  LDM          DECIMAL(25,3) Default 0,           -- LDM
  CBM          DECIMAL(25,3) Default 0,           -- CBM
  OverQnt      DECIMAL(25,3) Default 0,           -- Overload Quantity
  OPlace       VARCHAR(100),               -- Offloading Place
  Pack_Id      BIGINT Default 0,              -- نوع التغليف

  -- النقل والمعدات
  Track_Id     BIGINT Default 0,              -- نوع الشاحنة (دولي)
  TType_Id     BIGINT Default 0,              -- نوع الشاحنة (محلي/جمركي)
  Truck        VARCHAR(30),                -- رقم اللوحة
  Driver       VARCHAR(100),               -- اسم السائق (يدوي)
  AirLine_Id   BIGINT Default 0,              -- شركة الطيران
  ShipLine_Id  BIGINT Default 0,              -- شركة الشحن البحري
  TripNo       MEDIUMINT Default 1,              -- رقم الرحلة
  VTrip        VARCHAR(30),                -- رقم الرحلة النصي
  DTrip        DATETIME,                             -- تاريخ الرحلة
  CLType_Id    BIGINT Default 1,              -- CL Type: 1 FCL, 2 LCL
  TLType_Id    BIGINT Default 1,              -- TL Type: 1 FTL, 2 LTL
  TPNM         VARCHAR(30),                -- Track Pallet Number Main
  TPNT         VARCHAR(30),                -- Track Pallet Number Trella

  -- المالي والعملات
  Curn_Id      BIGINT Default 1,              -- العملة
  Curn_Rate    DECIMAL(25,9) Default 1,           -- سعر الصرف
  Amt          DECIMAL(25,3) Default 0,           -- القيمة
  CAmt         DECIMAL(25,3) Default 0,           -- القيمة بعملة الأصل
  Comm         DECIMAL(25,3) Default 0,           -- العمولة
  CComm        DECIMAL(25,3) Default 0,           -- العمولة بعملة الأصل
  DueDate      DATETIME,                             -- تاريخ الاستحقاق
  ODmrge       DECIMAL(7,2) Default 0,            -- تأخير المصدر (Demurrage)
  DDmrge       DECIMAL(7,2) Default 0,            -- تأخير المقصد (Demurrage)

  -- التواريخ الزمنية
  ETD          DATETIME,                             -- Estimated time of departure
  ETA          DATETIME,                             -- Estimated time of arrival
  ATD          DATETIME,                             -- Actual Time of Departure
  ATA          DATETIME,                             -- Actual Time of Arrival
  ArrODate     DATETIME,                             -- Arrival Date at Origin
  LoadDate     DATETIME,                             -- Loading Date
  DispDate     DATETIME,                             -- Dispatch Date
  ArrDDate     DATETIME,                             -- Arrival Date at Destination
  UDate        DATETIME,                             -- Unloading Date
  DocDate      DATETIME,                             -- Receive Documents Date
  CMRDate      DATETIME,                             -- CMR Date
  SDate        DATETIME,                             -- تاريخ الحالة / الإغلاق
  DelDate      DATETIME,                             -- تاريخ التسليم
  MDate        DATETIME,                             -- تاريخ الوثيقة الرئيسي
  HDate        DATETIME,                             -- تاريخ الوثيقة المحلي
  EDate        DATETIME,                             -- تاريخ الوثيقة express
  FDate        DATETIME,                             -- تاريخ رحلة الطيران
  KDocDate     DATETIME,                             -- تاريخ الوثيقة المرتبطة
  IDocDate     DATETIME,                             -- تاريخ البيان الجمركي دخول
  ODocDate     DATETIME,                             -- تاريخ البيان الجمركي خروج
  TKDocDate    DATETIME,                             -- تاريخ وثيقة النقل الإضافية

  -- الوثائق والمراجع
  MNum         VARCHAR(30),                -- رقم الوثيقة الرئيسي
  HNum         VARCHAR(30),                -- رقم الوثيقة المحلي
  ENum         VARCHAR(30),                -- رقم الوثيقة express
  FNum         VARCHAR(30),                -- رقم رحلة الطيران
  nRef         VARCHAR(30),                -- Reference Number
  BRef         VARCHAR(30),                -- Booking Reference Number
  POrder       VARCHAR(30),                -- Pickup Order Number
  Waybill      VARCHAR(30),                -- رقم وثيقة النقل
  DelNum       VARCHAR(10),                -- رقم التسليم
  KDocType_Id  BIGINT Default 0,              -- نوع الوثيقة المرتبطة
  KDocNum      VARCHAR(30),                -- رقم الوثيقة المرتبطة
  IDocType_Id  BIGINT Default 0,              -- نوع وثيقة الدخول
  IDocNum      VARCHAR(30),                -- رقم البيان دخول (Declaration)
  ODocType_Id  BIGINT Default 0,              -- نوع وثيقة الخروج
  ODocNum      VARCHAR(30),                -- رقم البيان خروج (Declaration)
  TKDocType_Id BIGINT Default 0,              -- نوع وثيقة النقل الإضافية
  TKDocNum     VARCHAR(30),                -- رقم وثيقة النقل الإضافية

  -- الحالات والأعلام
  Status_Id    BIGINT Default 0,              -- الحالة العامة
  SRem         VARCHAR(250),               -- ملاحظات الحالة
  DStatus_Id   BIGINT Default 2,              -- حالة التسليم
  OpStatus_Id  BIGINT Default 2,              -- حالة العملية
  OPSRem       VARCHAR(250),               -- ملاحظات حالة العملية
  PSStatus_Id  BIGINT Default 2,             -- ProfitShare Status
  Cooling_Id   BIGINT Default 2,              -- Cooling Status
  Cancel_Id    BIGINT Default 2,              -- Cancel Status

  -- التسليم والملاحظات
  DelPerson    VARCHAR(100),               -- المستلم (موحد من DelName/DPerson)
  DelRem       VARCHAR(100),               -- ملاحظات التسليم
  OrigRem      VARCHAR(250),               -- ملاحظات التحميل
  DestRem      VARCHAR(250),               -- ملاحظات التفريغ
  Rem          VARCHAR(250),               -- ملاحظات عامة
  vPath        VARCHAR(250),               -- المسار
  OverDist     VARCHAR(250),               -- Overdistance Place

  -- الربط والتدقيق
  Rel_Id       BIGINT,                        -- مفتاح ملف العمل المرتبط
  Ins_User     BIGINT, Ins_Date     DATETIME,
  Upd_User     BIGINT, Upd_Date     DATETIME,

  CONSTRAINT   Fre_Job_PK               Primary Key (Id),
  CONSTRAINT   Fre_Job_UK               Unique      (Dept_Id, Unit_Id, Period_Id, Num),
  CONSTRAINT   Fre_Job_Ins_FK           Foreign Key (Ins_User   ) References Cpy_User           (Id),
  CONSTRAINT   Fre_Job_Upd_FK           Foreign Key (Upd_User   ) References Cpy_User           (Id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

