  Module_Id     BIGINT Default 0,             -- نوع المقطع 1 جوي / 2 بري / 3 بحري
  nOrd          TINYINT Default 0,             -- الترتيب
  Airline_Id    BIGINT Default 0,             -- airLine
  Roadline_Id   BIGINT Default 0,             -- Train Line
  Shipline_Id   BIGINT Default 0,             -- Shipping Line
  OTCntry_Id    BIGINT Default 0,             -- بلد المصدر للمقطع
  OTCity_Id     BIGINT Default 0,             -- مدينة المصدر للمقطع
  OAPort_Id     BIGINT Default 0,             -- مطار المصدر للمقطع
  ORPort_Id     BIGINT Default 0,             -- معبر المصدر للمقطع
  OSPort_Id     BIGINT Default 0,             -- ميناء المصدر للمقطع
  OTAddress     VARCHAR(250),              -- عنوان المصدر للمقطع
  DTCntry_Id    BIGINT Default 0,             -- بلد المقصد للمقطع
  DTCity_Id     BIGINT Default 0,             -- مدينة المقصد للمقطع
  DAPort_Id     BIGINT Default 0,             -- مطار المقصد للمقطع
  DRPort_Id     BIGINT Default 0,             -- معبر المقصد للمقطع
  DSPort_Id     BIGINT Default 0,             -- ميناء المقصد للمقطع
  DTAddress     VARCHAR(250),              -- عنوان المقصد للمقطع
  BOLNo         VARCHAR(50),               -- Bill of Load
  BOLDate       DATETIME,                            -- تاريخ
  CLType_Id     BIGINT Default 1,             -- CL Type, 1 FCL, 2 LCL
  TLType_Id     BIGINT Default 1,             -- TL Type, 1 FTL, 2 LTL
  TType_Id      BIGINT Default 0,             -- Truck Type
  TPNM          VARCHAR(30),               -- Track Palet Number Main
  TPNT          VARCHAR(30),               -- Track Palet Number Trella
  Driver        VARCHAR(250),              -- اسم السائق
  VTrip         VARCHAR(30),               -- Trip Number
