Create Table Fre_Job_DBCR              -- الوثائق المدينة\الدائنة التابعة لملف عمل
( Id          BIGINT NOT NULL AUTO_INCREMENT,               -- مفتاح رئيسي
  Job_Id      BIGINT NOT NULL,               -- مفتاح ملف العمل
  nOrd        SMALLINT,                         -- مسلسل الإظهار
  Num         BIGINT,                        -- الرقم
  dDate       DATETIME,                              -- التاريخ
  Loc_Id      BIGINT Default 0,               -- المكان Location / 1 Origin / 2 Shipping / 3 Destination
  Trt_Id      BIGINT Default 11,              -- Trt Type / 11 Inv / 12 DBT / 21 CRD / 22 EXP
  Cont_Id     BIGINT Default 0,               -- المتعامل
  Serv_Id     BIGINT Default 0,               -- الخدمة
  Item_Id     BIGINT Default 0,               -- المادة
  Unit_Id     BIGINT Default 0,               -- الوحدة
  Curn_Id     BIGINT Default 1,               -- العملة
  Curn_Rate   DECIMAL(25,9) Default 1,            -- سعر الصرف
  Qnt         DECIMAL(25,3) Default 0,            -- الكمية
  Price       DECIMAL(25,3) Default 0,            -- إفرادي
  CAmt        DECIMAL(25,3) Default 0,            -- المبلغ عملة
  Amt         DECIMAL(25,2) Default 0,            -- المبلغ محلي
  nRef        VARCHAR(30),                 -- الرقم المرجع
  dRef        DATETIME,                              -- التاريخ المرجع
  Rem         VARCHAR(250),                -- البيان
  IFin_Id     BIGINT,                        -- مفتاخ لبند الفاتورة في التدقيق المالي
  DFin_Id     BIGINT,                        -- مفتاخ بند الوثيقة المدينة في التدقيق المالي
  CFin_Id     BIGINT,                        -- مفتاخ بند الوثيقة الدائنة في التدقيق المالي
  Status_Id   BIGINT Default 2,               -- حالة الموافقة من مدير القسم 0 جديدة \ 1 موافق عليها
  Dept_RId    BIGINT Default 0,               -- النشاط المقابل
  Unit_RId    BIGINT Default 0,               -- القسم المقابل
  Job_RId     BIGINT,                        -- مفتاح ملف العمل المقابل
  Ord_Id      BIGINT,                        -- مفتاح سلفة العمل
  Waybill     BIGINT,                        -- Waybill
  Ins_User    BIGINT, Ins_Date     DATETIME,
  Upd_User    BIGINT, Upd_Date     DATETIME,
  CONSTRAINT  Fre_Job_DBCR_PK        PRIMARY KEY (Id),
  CONSTRAINT  Fre_Job_DBCR_Job_FK    Foreign Key (Job_Id   ) References Fre_Job      (Id),
  CONSTRAINT  Fre_Job_DBCR_LOC_FK    Foreign Key (Loc_Id   ) References Fre_Cod_Loc  (Id),
  CONSTRAINT  Fre_Job_DBCR_Trt_FK    Foreign Key (Trt_Id   ) References Fre_Cod_Trt  (Id),
  CONSTRAINT  Fre_Job_DBCR_Cont_FK   Foreign Key (Cont_Id  ) References Mng_Cont     (Id),
  CONSTRAINT  Fre_Job_DBCR_Serv_FK   Foreign Key (Serv_Id  ) References Mng_Serv     (Id),
  CONSTRAINT  Fre_Job_DBCR_Unit_FK   Foreign Key (Unit_Id  ) References Cpy_Cod_Unit (Id),
  CONSTRAINT  Fre_Job_DBCR_Curn_FK   Foreign Key (Curn_Id  ) References Mng_Curn     (Id),
  CONSTRAINT  Fre_Job_DBCR_Status_FK Foreign Key (Status_Id) References Phs_Cod_YesNo(Id),
  CONSTRAINT  Fre_Job_DBCR_RDept_FK  Foreign Key (Dept_RId ) References Cpy_Dept     (Id),
  CONSTRAINT  Fre_Job_DBCR_RUnit_FK  Foreign Key (Unit_RId ) References Cpy_Unit     (Id),
  CONSTRAINT  Fre_Job_DBCR_Ins_FK    Foreign Key (Ins_User ) References Cpy_User     (Id),
  CONSTRAINT  Fre_Job_DBCR_Upd_FK    Foreign Key (Upd_User ) References Cpy_User     (Id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

