  Curn_Rate  DECIMAL(25,9) Default 1,             -- سعر الصرف
  nLength    DECIMAL(25,3) Default 0,             -- الوزن الصافي
  nWidth     DECIMAL(25,3) Default 0,             -- الوزن الصافي
  nHeight    DECIMAL(25,3) Default 0,             -- الوزن الصافي
  nVolume    DECIMAL(25,3) Default 0,             -- الحجم
  TCBM       DECIMAL(25,3) Default 0,             -- الوزن المحاسب عليه
