  LQnt       DECIMAL(25,3) Default 0,             -- Losses Quantity
  OQnt       DECIMAL(25,3) Default 0,             -- Overload Quantity
  WNet       DECIMAL(25,3) Default 0,             -- الوزن الصافي
  WGros      DECIMAL(25,3) Default 0,             -- الوزن الوزن القائم
  WChrg      DECIMAL(25,3) Default 0,             -- الوزن المحاسب عليه
  Price      DECIMAL(25,3) Default 0,             -- إفرادي
